INSERT INTO "profile" ("id","name_zh","name_en","email","address","short_bio","full_bio") VALUES(1,'黃振家','Cheng-Chia Huang','cchiahuang@fcu.edu.tw','逢甲大學 臺中市西屯區文華路100號','黃振家博士現任逢甲大學水利工程與資源保育學系副教授，研究聚焦水庫與河川泥砂運移、水庫防淤排砂、水工模型試驗、數值模擬及現地監測，並結合人工智慧、影像分析與數位孿生技術，發展水資源管理、災害預警及工程決策支援方法。',replace('黃振家博士長期投入水利工程、水資源、河川與水庫泥砂運移、防災預警及永續發展工作。研究方法涵蓋水工模型試驗、數值模擬、現地監測、影像分析、人工智慧及數位孿生。\n2009至2018年間，參與國立臺灣大學水工試驗所37件研究及工程計畫，累積水工模型、泥砂運移、現地監測、數值模擬及國際技術合作經驗。近年進一步結合資料科學與智慧化技術，應用於泥砂濃度預測、都市淹水辨識、災害預警及流域決策支援。\n除研究與教學外，現兼任逢甲大學永續處永續組組長，參與校級永續發展、跨單位協調及國際交流工作。','\n',char(10)));
