INSERT INTO "labs" ("id","name","description") VALUES(1,'STARLAB','STARLAB 聚焦水庫與河川泥砂運移、水工模型試驗、數值模擬、現地監測、人工智慧及數位孿生，並將研究成果應用於水庫防淤排砂、洪水泥砂預警、都市淹水辨識及流域決策支援。');
