INSERT INTO "research" ("id","title","description","photo","photo_position","sort_order","basin_location","representative_outcome") VALUES(1,'水庫與河川水砂治理','研究水庫淤積、異重流、河道沖淤及泥砂運移機制，探討防淤隧道、排砂操作及水庫庫容維持策略。研究方法包括水工模型試驗、數值模擬、現地監測及工程資料分析。','/uploads/1792579609431-6e7e28d5-cc1b-4ef2-b9ea-ebf12006385d.jpg',NULL,0,'水庫',NULL);
INSERT INTO "research" ("id","title","description","photo","photo_position","sort_order","basin_location","representative_outcome") VALUES(2,'水工模型與智慧量測','運用水工模型分析水流、泥砂、局部沖刷及排水效能，並導入影像分析、自動量測及即時資料處理方法，提升試驗資料的完整性與工程應用價值。','/uploads/1792579632986-6aa03fc5-e9f0-4077-aa2d-f49dc8cf977b.jpg',NULL,1,'河道',NULL);
INSERT INTO "research" ("id","title","description","photo","photo_position","sort_order","basin_location","representative_outcome") VALUES(3,'人工智慧與災害預警','結合機器學習、深度學習、影像辨識及物聯網技術，發展泥砂濃度預測、洪水泥砂聯合預警及都市淹水辨識方法。','/uploads/1792579683506-f46313b1-3d1f-4b5b-bd9b-2b5f6de8b0c1.jpg','12% 50%',2,'下游與都市',NULL);
INSERT INTO "research" ("id","title","description","photo","photo_position","sort_order","basin_location","representative_outcome") VALUES(4,'流域數位孿生','整合水文、水理、泥砂模式及現地監測資料，建置流域數位孿生與決策支援工具，應用於流域治理、災害預警及水資源管理。','/uploads/1792579721237-c8064bd2-075a-4f18-a2b8-64dd48f360bb.jpg','50% 48%',3,'集水區',NULL);
INSERT INTO "research" ("id","title","description","photo","photo_position","sort_order","basin_location","representative_outcome") VALUES(5,'都市防洪與氣候韌性','整合土地使用、排水規劃、防洪工程及氣候調適策略，評估都市淹水風險並發展跨領域治理方法。','/uploads/1792579738373-9e638ccc-e23e-4949-908a-b17820972053.jpg','100% 50%',4,'下游與都市',NULL);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(1,'2021 至 2026 年列有 16 篇期刊論文，其中 14 篇 SCIE 及 2 篇 EI。',1);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(2,'另列有 28 篇研討會論文及 1 件產業個案教材。',2);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(3,'2021 年後取得 3 件發明專利；另有 1 件早期共同發明專利。',3);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(4,'主持 18 件研究、產學、教學及國際人才培育計畫。',4);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(5,'共同主持 10 件計畫，協同主持 2 件計畫。',5);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(6,'指導 6 件國科會大專學生研究計畫。',6);
INSERT INTO "research_summaries" ("id","text","sort_order") VALUES(7,'2009 至 2018 年間參與 37 件臺大水工試驗所研究及工程計畫，包括 12 件水工模型與實驗驗證、17 件水庫河川泥砂與現地監測、4 件數值模擬與防災決策，以及 4 件臺美技術引進與國際合作。',7);
